<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {useFinance} from '@/composables/useFinance'
import {ApiError,asApiError} from '@/api/client'
import {getFinance,listFinance,financeConfirmations,financeBalances,financeEntries,financeReadiness,financeNotifications,financeEvidence,confirmationGate,evidenceIds,kindLabels,financeStatus,financeReasons,checks as reviewChecks,parseMoney,parseSignedMoney,type FinanceRecord,type FinanceKind,type ChildKind,type Rules,type Balances,type Entry,type Confirmation,type Readiness,type Notification,type ExternalLine} from '@/api/modules/finance'
import {listTrade,money,type TradeRecord} from '@/api/modules/trade'
import {listProjects,getProject,type ProjectRecord} from '@/api/modules/projects'
import {validSupplyId,shortSupplyId,type MediaType,type SupplyAsset} from '@/api/modules/supply'
import WorkspaceNav from '@/components/WorkspaceNav.vue'
import ApiErrorAlert from '@/components/ApiErrorAlert.vue'
import SupplyUpload from '@/components/SupplyUpload.vue'
import FinanceRulesForm,{type RulesDraft} from '@/components/FinanceRulesForm.vue'
import FinanceRecordPanel from '@/components/FinanceRecordPanel.vue'
import TradeRecordPanel from '@/components/TradeRecordPanel.vue'
import '@/styles/supply.css'
import '@/styles/trade.css'
import '@/styles/finance.css'
const session=useSessionStore(),route=useRoute(),router=useRouter()
const mode=computed(()=>String(route.meta.financeView||'list')),reviewer=computed(()=>mode.value==='review'),recordId=computed(()=>String(route.params.recordId||'')),section=computed(()=>String(route.params.section||'agreements'))
const context=()=>({token:session.token,accountId:session.account?.id||'',partyId:reviewer.value?null:session.selectedId,revision:session.revision,scope:route.fullPath})
const ui=useFinance(context),{rows,detail,nextCursor,error,notice,pending,busy,securityRevision,conflictRevision,retryAt}=ui
const agreements=ref<FinanceRecord[]>([]),agreement=ref<FinanceRecord|null>(null),records=ref<FinanceRecord[]>([]),orders=ref<TradeRecord[]>([]),releases=ref<ProjectRecord[]>([]),sourceRecord=ref<TradeRecord|ProjectRecord|null>(null),sourceParties=ref<string[]>([]),confirmations=ref<Confirmation[]>([]),balances=ref<Balances|null>(null),entries=ref<Entry[]>([]),entryCursor=ref<string|null>(null),readiness=ref<Readiness|null>(null),notifications=ref<Notification[]>([]),notificationCursor=ref<string|null>(null),assets=ref<string[]>([]),readAssets=ref<string[]>([]),rules=ref<Rules|null>(null)
const initializing=ref(true),pageLoading=ref(false),openId=ref(''),selectedAgreement=ref(''),decision=ref(''),reason=ref(''),conflicted=ref(false),reconfirm=ref(false),now=ref(Date.now()),verification=reactive<Record<string,boolean>>({})
const create=reactive({sourceType:'',sourceId:'',previous:'',environment:'',ruleId:''}),draft=reactive<RulesDraft>({version:'',time:'',condition:'',terms:'',lines:[]}),form=reactive({period:'',note:'',recipient:'',amount:'',outcome:'',reference:'',time:'',start:'',end:'',gross:'',refund:'',fee:'',tax:'',direction:'',original:'',category:'',message:'',action:'',provider:'',environment:''}),adjustment=ref<{party:string;amount:string}[]>([{party:'',amount:''},{party:'',amount:''}]),externalLines=ref<{record:string;direction:string;reference:string;amount:string}[]>([])
const g=computed(()=>agreement.value?.kind==='AGREEMENT'?agreement.value:null),canOwn=computed(()=>!!session.selected&&session.selected.membership.current_status==='ACTIVE'&&session.selected.membership.roles.includes('OWNER')&&!['CLOSED','SUSPENDED'].includes(session.selected.party.current_status)),isPayer=computed(()=>canOwn.value&&g.value?.owner_party_id===session.selectedId),locked=computed(()=>busy.value||!!pending.value||now.value<retryAt.value||conflicted.value&&!reconfirm.value),independent=computed(()=>reviewer.value&&!!detail.value&&detail.value.created_by!==session.account?.id&&g.value?.created_by!==session.account?.id&&!session.parties.some(a=>a.membership.current_status==='ACTIVE'&&g.value?.data.parties.includes(a.party.id))),gate=computed(()=>detail.value&&g.value?confirmationGate(detail.value,g.value,session.selectedId,confirmations.value):{can:false,message:'请先读取本版实际确认记录。'})
const childKinds:Record<string,ChildKind[]>={settlements:['SETTLEMENT'],payouts:['PAYOUT','PAYOUT_EVIDENCE'],income:['STATEMENT','RECEIPT','RECONCILIATION'],disputes:['DISPUTE','RESPONSE','ADJUSTMENT']}
const reviewKinds:Record<string,FinanceKind[]>={agreements:['AGREEMENT'],settlements:['SETTLEMENT'],payouts:['PAYOUT'],'payout-evidence':['PAYOUT_EVIDENCE'],revenue:['STATEMENT','RECEIPT'],adjustments:['ADJUSTMENT'],disputes:['DISPUTE']}
const reviewNames:Record<string,string>={agreements:'结算约定独立复核',settlements:'结算单独立复核',payouts:'付款申请独立复核','payout-evidence':'真实付款凭据独立核实',revenue:'渠道账单与到账独立核验',adjustments:'账务调整独立复核',disputes:'争议处置与补救核实'}
const title=computed(()=>reviewer.value?reviewNames[section.value]:mode.value==='list'?({agreements:'结算约定与本方余额',settlements:'期间结算单',payouts:'付款申请与真实结果',income:'渠道账单与实际到账',disputes:'争议与账务调整'} as Record<string,string>)[section.value]:String(route.meta.title)),gallery=computed(()=>reviewer.value?({agreements:'WEB-27-02-v2',settlements:'WEB-28-03-v2',payouts:'WEB-29-02-v2','payout-evidence':'WEB-29-04-v2',revenue:'WEB-30-03',adjustments:'WEB-31-04-v2',disputes:'WEB-31-02-v2'} as Record<string,string>)[section.value]:({new:'WEB-27-01',list:'WEB-28-01-v4',agreement:'WEB-28-01-v4','confirm-agreement':'WEB-27-03-v3',settlement:'WEB-28-02-v2','confirm-settlement':'WEB-28-04-v2',payout:'WEB-29-01-v2',evidence:'WEB-29-03-v2',statement:'WEB-30-01-v2',receipt:'WEB-30-02-v2',reconcile:'WEB-30-04-v2',dispute:'WEB-31-01-v2',respond:'WEB-31-01-v2',adjustment:'WEB-31-03',readiness:'WEB-35-01-v2'} as Record<string,string>)[mode.value]||'WEB-28-01-v4')
const date=(value:string)=>value&&Number.isFinite(Date.parse(value))?new Date(value).toISOString():''
const past=(value:string)=>!!date(value)&&Date.parse(value)<=Date.now()
const positive=(value:string)=>{const n=parseMoney(value);return n!==null&&n>0}
const reviewValid=computed(()=>independent.value&&!!detail.value&&['IN_REVIEW','REQUESTED'].includes(detail.value.current_status)&&['APPROVED','REJECTED'].includes(decision.value)&&reason.value.trim()&&(decision.value!=='APPROVED'||Object.keys(reviewChecks).every(k=>verification[k])&&evidenceIds(detail.value).every(id=>readAssets.value.includes(id))))
const createValid=computed(()=>canOwn.value&&sourceRecord.value?.id===create.sourceId&&sourceParties.value.length>0&&['SANDBOX','PRODUCTION'].includes(create.environment)&&validSupplyId(create.ruleId)&&!!rules.value&&assets.value.length===1&&(!create.previous||agreements.value.some(r=>r.kind==='AGREEMENT'&&r.id===create.previous&&r.data.source_id===create.sourceId)))
const sourceOptions=computed(()=>create.sourceType==='ORDER'?orders.value:releases.value)
const payoutValid=computed(()=>canOwn.value&&g.value&&g.value.data.parties.includes(form.recipient)&&form.recipient!==g.value.owner_party_id&&(isPayer.value||form.recipient===session.selectedId)&&positive(form.amount)&&assets.value.length===1&&form.note.trim())
const statementNet=computed(()=>{const values=[form.gross,form.refund,form.fee,form.tax].map(parseMoney);return values.every(v=>v!==null)?values[0]!-values[1]!-values[2]!-values[3]!:null})
const statementValid=computed(()=>isPayer.value&&g.value?.data.source_type==='RELEASE'&&form.reference.trim()&&past(form.start)&&past(form.end)&&date(form.start)<date(form.end)&&statementNet.value!==null&&statementNet.value>=0&&['CREDIT','DEBIT'].includes(form.direction)&&(form.direction==='CREDIT'?!form.original:records.value.some(r=>r.kind==='STATEMENT'&&r.id===form.original&&r.current_status==='APPROVED'&&r.data.direction==='CREDIT'))&&assets.value.length===1&&form.note.trim())
const adjustmentValid=computed(()=>isPayer.value&&adjustment.value.length>=2&&adjustment.value.length<=30&&new Set(adjustment.value.map(e=>e.party)).size===adjustment.value.length&&adjustment.value.every(e=>g.value?.data.parties.includes(e.party)&&parseSignedMoney(e.amount)!==null)&&adjustment.value.reduce((n,e)=>n+(parseSignedMoney(e.amount)||0),0)===0&&reason.value.trim()&&assets.value.length===1)
let disposed=false,pageTicket=0,timer=0
function resetDecision(){decision.value=reason.value='';readAssets.value=[];Object.keys(verification).forEach(k=>delete verification[k]);ui.revoke()}
function reset(){pageTicket++;pageLoading.value=false;agreements.value=[];agreement.value=null;records.value=[];orders.value=[];releases.value=[];sourceRecord.value=null;sourceParties.value=[];confirmations.value=[];balances.value=null;entries.value=[];entryCursor.value=null;readiness.value=null;notifications.value=[];notificationCursor.value=null;assets.value=[];rules.value=null;openId.value=selectedAgreement.value='';Object.keys(create).forEach(k=>create[k as keyof typeof create]='');Object.keys(form).forEach(k=>form[k as keyof typeof form]='');draft.version=draft.time=draft.condition=draft.terms='';draft.lines=[];adjustment.value=[{party:'',amount:''},{party:'',amount:''}];externalLines.value=[];conflicted.value=reconfirm.value=false;resetDecision()}
watch(securityRevision,reset,{flush:'sync'})
watch(conflictRevision,()=>{resetDecision();form.outcome=form.action='';confirmations.value=[];balances.value=null;readiness.value=null;conflicted.value=true;reconfirm.value=false;void loadPage()},{flush:'sync'})
watch(()=>[route.fullPath,session.selectedId,session.revision],()=>{if(!initializing.value)void loadPage()})
watch(()=>create.sourceType,()=>{create.sourceId=create.previous='';sourceRecord.value=null;sourceParties.value=[];draft.lines=[];rules.value=null})
watch(()=>create.sourceId,()=>{create.previous='';sourceRecord.value=null;sourceParties.value=[];draft.lines=[];rules.value=null;void chooseSource()})
async function allAgreements(){await ui.read('agreements',async(i,s)=>{const result:FinanceRecord[]=[],seen=new Set<string>();let cursor:string|null=null;do{const page=await listFinance(i,undefined,undefined,cursor,s);result.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'约定分页未更新。'});if(cursor)seen.add(cursor)}while(cursor);return result},r=>agreements.value=r)}
async function collections(id:string,kinds:ChildKind[]){const ticket=pageTicket,all:FinanceRecord[]=[];for(const kind of kinds){const result=await ui.loadAll(id,kind);if(!result||disposed||ticket!==pageTicket)return;all.push(...result)}records.value=all}
async function sources(){await ui.read('source-orders',async(i,s)=>{const all:TradeRecord[]=[],seen=new Set<string>();let cursor:string|null=null;do{const page=await listTrade(i,'ORDER',cursor,s);all.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'订单分页未更新。'});if(cursor)seen.add(cursor)}while(cursor);return all.filter(r=>r.kind==='ORDER'&&r.merchant_party_id===i.partyId)},r=>orders.value=r);if(!canOwn.value)return;await ui.read('source-releases',async(i,s)=>{const projects:ProjectRecord[]=[],all:ProjectRecord[]=[],seen=new Set<string>();let cursor:string|null=null;do{const page=await listProjects(i,undefined,undefined,cursor,s);projects.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'发行项目分页未更新。'});if(cursor)seen.add(cursor)}while(cursor);for(const p of projects.filter(p=>p.owner_party_id===i.partyId)){cursor=null;seen.clear();do{const page=await listProjects(i,p.id,'RELEASE',cursor,s);all.push(...page.items);cursor=page.next_cursor;if(cursor&&seen.has(cursor))throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'发行记录分页未更新。'});if(cursor)seen.add(cursor)}while(cursor)}return all.filter(r=>r.kind==='RELEASE'&&['EXTERNAL_PUBLISHED','EXTERNAL_WITHDRAWN'].includes(r.current_status))},r=>releases.value=r)}
async function chooseSource(){const id=create.sourceId,type=create.sourceType,r=sourceOptions.value.find(r=>r.id===id);if(!r)return;sourceRecord.value=r;if(r.kind==='ORDER'){const commercial=r.data.quote.commercial;sourceParties.value=[...new Set([r.merchant_party_id,r.buyer_party_id!,...r.data.quote.lines.map(l=>l.provider_party_id),...(commercial?.relation?[commercial.relation.mcn_party_id]:[])])];draft.lines=r.data.quote.lines.map(l=>({id:l.line_id,shares:[{party:'',role:'',percent:''}],fees:[]}))}else if(r.kind==='RELEASE'){await ui.read('source-edition',(i,s)=>getProject(i,r.data.edition_id,'EDITION',s),edition=>{if(create.sourceId!==id||create.sourceType!==type||edition.kind!=='EDITION')return;sourceParties.value=[...new Set([r.owner_party_id,...edition.data.confirmers.map(c=>c.party_id)])];draft.lines=[{id:'revenue',shares:[{party:'',role:'',percent:''}],fees:[]}]})}}
async function loadConfirmations(id:string){confirmations.value=[];await ui.read('confirmations',(i,s)=>financeConfirmations(i,id,s),r=>confirmations.value=r.items)}
async function refreshBalance(){const r=g.value;if(!r)return;balances.value=null;await ui.read('balances',(i,s)=>financeBalances(i,r.id,r.owner_party_id,s),r=>balances.value=r)}
async function loadEntries(more=false){const r=g.value;if(!r||more&&!entryCursor.value)return;const cursor=more?entryCursor.value:null;await ui.read('entries',(i,s)=>financeEntries(i,r.id,r.owner_party_id,cursor,s),v=>{if(v.next_cursor&&v.next_cursor===cursor)throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'账务分页未更新。'});entries.value=more?[...entries.value,...v.items]:v.items;entryCursor.value=v.next_cursor})}
async function refreshReadiness(){if(!g.value)return;const id=g.value.id;readiness.value=null;await ui.read('readiness',(i,s)=>financeReadiness(i,id,s),r=>readiness.value=r)}
async function loadNotifications(more=false){const cursor=more?notificationCursor.value:null;if(more&&!cursor)return;await ui.read('notifications',(i,s)=>financeNotifications(i,cursor,s),r=>{if(r.next_cursor&&r.next_cursor===cursor)throw new ApiError({status:200,code:'UNEXPECTED_RESPONSE_SHAPE',message:'事件分页未更新。'});notifications.value=more?[...notifications.value,...r.items]:r.items;notificationCursor.value=r.next_cursor})}
async function loadPage(){const ticket=++pageTicket,current=()=>!disposed&&ticket===pageTicket;pageLoading.value=true;resetDecision();try{
 if(mode.value==='new'){await allAgreements();if(!current())return;await sources();if(!current())return;const type=route.query.sourceType,id=route.query.sourceId;if((type==='ORDER'||type==='RELEASE')&&typeof id==='string'){create.sourceType=type;await Promise.resolve();if(sourceOptions.value.some(r=>r.id===id))create.sourceId=id;else error.value=new ApiError({status:400,code:'CLIENT_SOURCE_INVALID',message:'当前身份的真实来源列表中没有此记录；请核对原订单或发行权限。'})}return}
 if(!recordId.value){await allAgreements();if(!current())return;if(reviewer.value){if(section.value==='agreements'){records.value=agreements.value;return}const all:FinanceRecord[]=[];for(const a of agreements.value){for(const kind of reviewKinds[section.value]||[]){const r=await ui.loadAll(a.id,kind as ChildKind);if(!current()||!r)return;all.push(...r)}}records.value=all;return}if(selectedAgreement.value){const a=agreements.value.find(a=>a.id===selectedAgreement.value);if(a){agreement.value=a;await collections(a.id,childKinds[section.value]||[])}}return}
 if(!validSupplyId(recordId.value)){error.value=new ApiError({status:400,code:'CLIENT_RECORD_INVALID',message:'请填写完整的真实财务记录编号。'});return}
 const expected:FinanceKind|undefined=['agreement','settlement','payout','statement','adjustment','reconcile','readiness','confirm-agreement'].includes(mode.value)?'AGREEMENT':mode.value==='confirm-settlement'?'SETTLEMENT':mode.value==='evidence'?'PAYOUT':mode.value==='receipt'?'STATEMENT':mode.value==='respond'?'DISPUTE':reviewer.value&&reviewKinds[section.value]?.length===1?reviewKinds[section.value]![0]:undefined
 const r=await ui.loadRecord(recordId.value,expected);if(!r||!current())return;if(reviewer.value&&!reviewKinds[section.value]?.includes(r.kind)){error.value=new ApiError({status:400,code:'CLIENT_RECORD_INVALID',message:'此记录不属于当前独立核验事项。'});detail.value=null;return}
 if(r.kind==='AGREEMENT')agreement.value=r;else if(r.agreement_id)await ui.read('agreement',(i,s)=>getFinance(i,r.agreement_id!,'AGREEMENT',s),r=>agreement.value=r);if(!current()||!g.value)return
 if(['confirm-agreement','confirm-settlement'].includes(mode.value))await loadConfirmations(r.id);if(!current())return
 if(mode.value==='agreement'){await refreshBalance();if(!current())return;await loadEntries();if(!current())return;await collections(g.value.id,['SETTLEMENT','PAYOUT','DISPUTE']);return}
 if(mode.value==='payout'){await refreshBalance();return}
 if(mode.value==='readiness'){await refreshReadiness();return}
 if(mode.value==='statement')await collections(g.value.id,['STATEMENT'])
 if(mode.value==='respond'||reviewer.value&& section.value==='disputes')await collections(g.value.id,['RESPONSE','ADJUSTMENT'])
 }finally{if(current())pageLoading.value=false}}
function leave(){if(ui.canNavigate())return true;notice.value='原财务操作结果尚未确认，请先核对并使用原请求恢复。';return false}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave)
function beforeUnload(e:BeforeUnloadEvent){if(!ui.canNavigate()){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{timer=window.setInterval(()=>now.value=Date.now(),1000);window.addEventListener('beforeunload',beforeUnload);const c=session.capture();try{await Promise.all([session.loadAccount(),session.loadParties()]);if(!disposed&&session.current(c)){initializing.value=false;await loadPage()}}catch(e){if(!disposed&&session.current(c)){ui.clear();error.value=asApiError(e)}}finally{if(!disposed)initializing.value=false}})
onUnmounted(()=>{disposed=true;pageTicket++;window.clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload)})
function openRecord(){if(!validSupplyId(openId.value)||locked.value)return;void router.push(reviewer.value?`/finance/reviews/${section.value}/${openId.value}`:`/finance/records/${openId.value}`)}
async function upload(file:File,media:MediaType){if(locked.value||!canOwn.value)return;const path=`/supply/assets?${new URLSearchParams({purpose:'RIGHTS_EVIDENCE',media_type:media})}`;await ui.write({path,resultKind:'ASSET',label:'上传财务私有证明',supply:{path,blob:file,mediaType:media,purpose:'RIGHTS_EVIDENCE',kind:'ASSET',label:'上传财务私有证明'}},r=>assets.value=[...assets.value,(r as SupplyAsset).id])}
function removeAsset(id:string){assets.value=assets.value.filter(a=>a!==id)}
async function createAgreement(){if(locked.value||!createValid.value)return;await ui.write({path:'/finance/agreements',resultKind:'AGREEMENT',label:'提交结算约定新版本',body:{source_type:create.sourceType,source_id:create.sourceId,previous_agreement_id:create.previous||null,environment:create.environment,rule_id:create.ruleId,rules:rules.value,evidence_asset_id:assets.value[0]}},r=>void router.push(`/finance/agreements/${r.id}`))}
async function submitChild(kind:ChildKind,path:string,body:unknown,label:string,target=detail.value){if(locked.value||!target||!g.value||!canOwn.value)return;await ui.write({path,targetId:target.id,agreementId:g.value.id,version:target.object_version,resultKind:kind,label,body},r=>void router.push(`/finance/records/${r.id}`))}
const settle=()=>{if(!isPayer.value||!form.period.trim()||!form.note.trim())return;return submitChild('SETTLEMENT',`/finance/agreements/${g.value!.id}/settlements`,{period_reference:form.period.trim(),note:form.note.trim()},'生成冻结期间结算单',g.value)}
const payout=()=>{if(!payoutValid.value)return;return submitChild('PAYOUT',`/finance/agreements/${g.value!.id}/payouts`,{recipient_party_id:form.recipient,amount_minor:parseMoney(form.amount),destination_asset_id:assets.value[0],note:form.note.trim()},'提交付款申请',g.value)}
const reportEvidence=()=>{const r=detail.value;if(!isPayer.value||r?.kind!=='PAYOUT'||!['PAID','FAILED','RETURNED'].includes(form.outcome)||(form.outcome==='RETURNED'?r.current_status!=='PAID':r.current_status!=='APPROVED')||parseMoney(form.amount)!==r.data.amount_minor||!form.reference.trim()||!past(form.time)||!form.note.trim()||assets.value.length!==1)return;return submitChild('PAYOUT_EVIDENCE',`/finance/payouts/${r.id}/evidence`,{outcome:form.outcome,amount_minor:parseMoney(form.amount),external_reference:form.reference.trim(),occurred_at:date(form.time),evidence_asset_id:assets.value[0],note:form.note.trim()},'登记真实全额付款报告',r)}
const statement=()=>{if(!statementValid.value)return;return submitChild('STATEMENT',`/finance/agreements/${g.value!.id}/statements`,{external_reference:form.reference.trim(),period_start:date(form.start),period_end:date(form.end),gross_minor:parseMoney(form.gross),refund_minor:parseMoney(form.refund),channel_fee_minor:parseMoney(form.fee),tax_minor:parseMoney(form.tax),direction:form.direction,original_statement_id:form.original||null,evidence_asset_id:assets.value[0],note:form.note.trim()},'登记渠道应收账单',g.value)}
const receipt=()=>{const r=detail.value;if(!isPayer.value||r?.kind!=='STATEMENT'||r.current_status!=='APPROVED'||r.data.direction!=='CREDIT'||!positive(form.amount)||!form.reference.trim()||!past(form.time)||assets.value.length!==1||!form.note.trim())return;return submitChild('RECEIPT',`/finance/statements/${r.id}/receipts`,{amount_minor:parseMoney(form.amount),external_reference:form.reference.trim(),occurred_at:date(form.time),evidence_asset_id:assets.value[0],note:form.note.trim()},'登记实际到账待核验',r)}
const adjust=()=>{if(!adjustmentValid.value)return;return submitChild('ADJUSTMENT',`/finance/agreements/${g.value!.id}/adjustments`,{entries:adjustment.value.map(e=>({party_id:e.party,amount_minor:parseSignedMoney(e.amount)})),reason:reason.value.trim(),evidence_asset_id:assets.value[0]},'登记零和账务调整',g.value)}
const dispute=()=>{const r=detail.value;if(!canOwn.value||!r||!form.category||!reason.value.trim()||!assets.value.length||assets.value.length>30)return;return submitChild('DISPUTE',`/finance/records/${r.id}/disputes`,{category:form.category,reason:reason.value.trim(),evidence_asset_ids:[...assets.value]},'发起业务异议',r)}
const respond=()=>{const r=detail.value;if(!canOwn.value||r?.kind!=='DISPUTE'||!['OPEN','ACTION_REQUIRED'].includes(r.current_status)||!form.message.trim()||assets.value.length>30)return;return submitChild('RESPONSE',`/finance/disputes/${r.id}/responses`,{message:form.message.trim(),evidence_asset_ids:[...assets.value]},'保存争议补充说明',r)}
async function reconcile(){if(!isPayer.value||g.value?.data.source_type!=='ORDER'||!['APPLE','ALIPAY'].includes(form.provider)||!['SANDBOX','PRODUCTION'].includes(form.environment)||form.environment!==g.value.data.environment||!form.reference.trim()||assets.value.length!==1||externalLines.value.length>200||new Set(externalLines.value.map(e=>e.record)).size!==externalLines.value.length||!externalLines.value.every(e=>validSupplyId(e.record)&&['RECEIPT','REFUND'].includes(e.direction)&&e.reference.trim()&&parseMoney(e.amount)!==null))return;await submitChild('RECONCILIATION',`/finance/agreements/${g.value.id}/reconciliations`,{provider:form.provider,environment:form.environment,external_reference:form.reference.trim(),items:externalLines.value.map(e=>({record_id:e.record,direction:e.direction as ExternalLine['direction'],external_reference:e.reference.trim(),amount_minor:parseMoney(e.amount)})),evidence_asset_id:assets.value[0]},'保存支付渠道比较结果',g.value)}
async function confirm(){const r=detail.value;if(!r||!canOwn.value||!gate.value.can||locked.value||!['APPROVED','REJECTED'].includes(decision.value)||!reason.value.trim())return;await ui.write({path:`/finance/records/${r.id}/confirmations`,targetId:r.id,agreementId:r.agreement_id||undefined,version:r.object_version,resultKind:r.kind,confirmation:true,label:'保存本方准确版本确认',body:{content_sha256:r.content_sha256,decision:decision.value,reason:reason.value.trim()}},()=>void loadPage())}
async function review(){const r=detail.value;if(!r||!reviewValid.value||locked.value)return;await ui.write({path:`/finance/records/${r.id}/reviews`,targetId:r.id,agreementId:r.agreement_id||undefined,version:r.object_version,resultKind:r.kind,label:'保存独立财务核验',body:{decision:decision.value,reason:reason.value.trim(),verification:Object.fromEntries(Object.keys(reviewChecks).map(k=>[k,!!verification[k]]))}},()=>void loadPage())}
async function decideDispute(){const r=detail.value;if(!r||r.kind!=='DISPUTE'||!independent.value||locked.value||!['OPEN','ACTION_REQUIRED'].includes(r.current_status)||!['ACTION_REQUIRED','RESUME','REMEDIED'].includes(decision.value)||!reason.value.trim()||decision.value==='REMEDIED'&&!validSupplyId(form.action))return;await ui.write({path:`/finance/disputes/${r.id}/decisions`,targetId:r.id,agreementId:r.agreement_id!,version:r.object_version,resultKind:'DISPUTE',label:'保存独立争议处理决定',body:{decision:decision.value,reason:reason.value.trim(),action_record_id:decision.value==='REMEDIED'?form.action:null}},()=>void loadPage())}
async function cancelPayout(){const r=detail.value;if(r?.kind!=='PAYOUT'||!canOwn.value||!(isPayer.value||r.data.recipient_party_id===session.selectedId)||r.current_status!=='REQUESTED'||!reason.value.trim()||locked.value)return;await ui.write({path:`/finance/payouts/${r.id}/cancellation`,targetId:r.id,agreementId:r.agreement_id!,version:r.object_version,resultKind:'PAYOUT',label:'取消未执行付款申请',body:{reason:reason.value.trim()}},()=>void loadPage())}
async function readEvidence(id:string){const r=detail.value;if(!r||locked.value||!evidenceIds(r).includes(id))return;await ui.read('evidence',(i,s)=>financeEvidence(i,r.id,id,s),blob=>{const url=ui.objectUrl(blob),a=document.createElement('a');a.href=url;a.download=`财务私有证明-${id}.bin`;a.click();readAssets.value=[...new Set([...readAssets.value,id])];notice.value='已通过当前权限接口读取私有证明。请实际核对内容后填写结论。'})}
function recordLink(r:FinanceRecord){return reviewer.value?`/finance/reviews/${section.value}/${r.id}`:r.kind==='AGREEMENT'?`/finance/agreements/${r.id}`:`/finance/records/${r.id}`}
</script>
<template><div class="supply-workspace trade-workspace finance-workspace" :data-gallery="gallery"><header class="supply-header"><RouterLink to="/workspace" class="supply-brand">晶晶日上</RouterLink><span>运营与合作方工作台</span><div class="account-actions"><span class="account-name">{{session.account?.display_name||'当前账号'}}</span><button @click="session.logout().then(()=>router.push('/login'))">退出</button></div></header><div class="supply-layout"><aside class="supply-sidebar"><WorkspaceNav/><div class="supply-identity"><template v-if="reviewer"><p>独立财务核验</p><p class="muted">以当前账号办理，不传办理主体。真实读取与提交均由服务器核验 FINANCE_REVIEW，参与方不得自审。</p></template><template v-else><label>当前办理身份<select data-testid="finance-party" :value="session.selectedId" :disabled="locked" @change="session.selectParty(($event.target as HTMLSelectElement).value)"><option v-for="a in session.parties" :key="a.party.id" :value="a.party.id">{{a.party.display_name}}</option></select></label><p class="muted">{{canOwn?'有效负责人身份':'当前不是有效负责人，业务写入不可用'}}</p></template></div></aside><main class="supply-main"><div class="supply-heading"><div><h1>{{title}}</h1><p>{{reviewer?'核对保存的约定、金额与真实凭据，独立记录本次决定。':'逐约定办理财务事实；申请、应收、报告与实际核实结果分别保存。'}}</p></div><button class="outline" :disabled="locked||pageLoading" @click="loadPage" data-testid="finance-refresh">刷新当前记录</button></div><div class="loaded-tabs"><template v-if="reviewer"><RouterLink v-for="(label,key) in reviewNames" :key="key" :to="`/finance/reviews/${key}`" :class="{active:section===key}">{{label}}</RouterLink></template><template v-else><RouterLink to="/finance/agreements">结算约定与余额</RouterLink><RouterLink to="/finance/settlements">期间结算单</RouterLink><RouterLink to="/finance/payouts">付款申请与结果</RouterLink><RouterLink to="/finance/income">渠道应收与到账</RouterLink><RouterLink to="/finance/disputes">异议与调整</RouterLink></template></div><ApiErrorAlert :error="error"/><p v-if="notice" class="supply-notice" role="status">{{notice}}</p><div v-if="pending" class="supply-warning"><p>{{pending.command.label}}结果尚未确认。原请求、内容、文件及版本仍保留。</p><details><summary>查看原请求与已知结果</summary><p class="identifier">{{pending.key}}</p><p v-if="pending.resultId" class="identifier">{{pending.resultId}}</p></details><div class="supply-actions"><button class="outline" data-testid="finance-recovery-check" :disabled="busy||now<retryAt" @click="ui.checkPending()">核对原操作</button><button v-if="!pending.resultId&&pending.state!=='blocked'" class="primary" data-testid="finance-recovery-retry" :disabled="busy||!pending.checked||now<retryAt" @click="ui.retry()">使用原请求重试</button><button v-if="pending.state==='blocked'" class="outline" :disabled="busy||!pending.checked" @click="ui.endBlocked()">结束已拒绝上传的核对</button></div></div><div v-if="conflicted" class="supply-warning"><label class="trade-check"><input v-model="reconfirm" type="checkbox" data-testid="finance-reconfirm">我已读取最新记录，将重新填写并作出决定。</label></div><p v-if="initializing||pageLoading" class="supply-empty" role="status">正在读取身份与财务记录…</p><div v-else :key="route.fullPath+securityRevision">
<template v-if="!recordId&&mode!=='new'"><section class="supply-card"><div class="section-heading"><h2>{{reviewer?'获准核验的财务事项':'我参与的结算约定'}}</h2><RouterLink v-if="!reviewer" to="/finance/agreements/new" class="button-link primary">建立结算约定</RouterLink></div><label v-if="!reviewer&& section!=='agreements'">选择当前约定<select v-model="selectedAgreement" data-testid="finance-agreement-select" :disabled="locked" @change="loadPage"><option value="">请选择实际参与的约定</option><option v-for="r in agreements" :key="r.id" :value="r.id">{{shortSupplyId(r.id)}} · {{financeStatus(r)}}</option></select></label><div v-if="(reviewer||section!=='agreements'?records:agreements).length" class="table-wrap"><table><thead><tr><th>事项与期间</th><th>当前状态</th><th>金额 / 来源</th><th>操作</th></tr></thead><tbody><tr v-for="r in (reviewer||section!=='agreements'?records:agreements)" :key="r.id"><td>{{kindLabels[r.kind]}}<span v-if="r.kind==='SETTLEMENT'"> · {{r.data.period_reference}}</span><br><span class="muted">{{shortSupplyId(r.id)}}</span></td><td>{{financeStatus(r)}}</td><td>{{'amount_minor' in r.data?money(r.data.amount_minor):r.kind==='STATEMENT'?money(r.data.net_minor):r.kind==='AGREEMENT'?`${r.data.source_type} · ${shortSupplyId(r.data.source_id)}`:'按原记录核对'}}</td><td><RouterLink :to="recordLink(r)" class="table-link">{{reviewer?'读取并独立核验':'打开财务记录'}}</RouterLink></td></tr></tbody></table></div><p v-else class="supply-empty">尚无已读取的可见财务事项。{{!reviewer&& section!=='agreements'?'请先选择实际约定。':''}}</p></section><section class="supply-card"><h2>读取已知记录</h2><div class="trade-fields two"><label>完整真实记录编号<input v-model="openId" data-testid="finance-open-id" placeholder="未知编号不会生成演示记录"></label><button class="outline" data-testid="finance-open" :disabled="locked||!validSupplyId(openId)" @click="openRecord">读取财务记录</button></div></section><section v-if="!reviewer" class="supply-card"><h2>本办理身份的财务事件</h2><p class="muted">这里只读取当前主体获准的财务事件；没有全站通知或自动推送。</p><button class="outline" :disabled="locked" data-testid="finance-notifications" @click="loadNotifications()">读取本方财务事件</button><div v-for="n in notifications" :key="n.id" class="finance-rule-line"><RouterLink :to="`/finance/records/${n.record_id}`">{{n.event_code}} · {{shortSupplyId(n.record_id)}}</RouterLink></div><button v-if="notificationCursor" class="outline" :disabled="locked" @click="loadNotifications(true)">继续读取事件</button></section></template>
<form v-if="mode==='new'" @submit.prevent="createAgreement"><fieldset :disabled="locked||!canOwn"><section class="supply-card"><h2>准确来源与约定版本</h2><div class="trade-fields two"><label>来源类型 *<select v-model="create.sourceType" data-testid="finance-source-type" required><option value="">明确选择</option><option value="ORDER">服务订单</option><option value="RELEASE">真实发行</option></select></label><label>实际来源 *<select v-model="create.sourceId" data-testid="finance-source-id" required><option value="">请选择当前身份的真实来源</option><option v-for="r in sourceOptions" :key="r.id" :value="r.id">{{r.id}} · {{r.current_status}}</option></select></label><label>执行环境 *<select v-model="create.environment" data-testid="finance-environment" required><option value="">明确选择</option><option value="SANDBOX">沙盒</option><option value="PRODUCTION">正式</option></select></label><label>治理规则编号 *<input v-model="create.ruleId" data-testid="finance-rule-id" required placeholder="完整且已生效的真实规则编号"></label></div><label>前版约定（首次留空）<select v-model="create.previous" data-testid="finance-previous"><option value="">首次约定</option><option v-for="r in agreements.filter(r=>r.kind==='AGREEMENT'&&r.data.source_id===create.sourceId)" :key="r.id" :value="r.id">{{r.id}} · {{financeStatus(r)}}</option></select></label><p class="muted">没有公开的治理规则选择目录；规则须由服务器核验当前有效版本。已生效或形成财务历史的约定不能被新版本覆盖。</p><RouterLink to="/contracts" class="table-link">核对已知合同与规则</RouterLink><details v-if="sourceRecord" class="trade-rules"><summary>核对原来源与商业条款</summary><TradeRecordPanel v-if="sourceRecord.kind==='ORDER'" :record="sourceRecord"/><p v-else class="identifier">{{sourceRecord.id}} · {{sourceRecord.content_sha256}}</p></details></section><FinanceRulesForm :draft="draft" :parties="sourceParties" :disabled="locked" @change="rules=$event"/><section class="supply-card"><h2>各方约定的真实依据</h2><SupplyUpload :key="securityRevision" label="结算约定证明" :ids="assets" :disabled="locked" single @upload="upload" @remove="removeAsset"/><p class="muted">登记不等于真实签署；先独立复核，再由各方逐版明确确认。</p><button class="primary" data-testid="finance-agreement-submit" :disabled="locked||!createValid">提交约定独立复核</button></section></fieldset></form>
<template v-if="mode==='agreement'&&g"><section class="supply-card"><div class="section-heading"><h2>本约定的实收、应收与可申请额度</h2><button class="outline" data-testid="finance-balance-refresh" :disabled="locked" @click="refreshBalance">重新核对余额</button></div><p v-if="balances">{{balances.environment==='SANDBOX'?'沙盒':'正式'}} · 已核实实收 {{money(balances.received_minor)}} · 当前应收 {{money(balances.receivable_minor)}}</p><p class="muted">客户向商家付出的交易款与本约定下的人工付款分开记录。普通参与方只读取本方余额；商家保留金额不再次转给自己。</p><div v-if="balances" class="table-wrap" data-testid="finance-balances"><table><thead><tr><th>获准主体</th><th>计提 / 调整</th><th>已核实实付</th><th>余额 / 可申请</th><th>当前条件</th></tr></thead><tbody><tr v-for="b in balances.items" :key="b.party_id"><td>{{shortSupplyId(b.party_id)}}</td><td>{{money(b.accrued_minor)}} / {{money(b.adjustment_minor)}}</td><td>{{money(b.paid_minor)}}</td><td>{{money(b.balance_minor)}} / {{money(b.available_minor)}}<p v-if="b.recovery_due_minor">需另核实追回 {{money(b.recovery_due_minor)}}</p></td><td>{{b.reason_code?(financeReasons[b.reason_code]||b.reason_code):'当前可申请'}}<br>{{b.meaning==='MERCHANT_RETAINED_NOT_TRANSFER'?'商家保留，不再转给自己':'待按流程实际付出'}}</td></tr></tbody></table></div><div class="supply-actions"><RouterLink :to="`/finance/agreements/${g.id}/confirm`" class="button-link outline">本方确认约定</RouterLink><RouterLink v-if="isPayer" :to="`/finance/agreements/${g.id}/settlements/new`" class="button-link outline">生成期间结算单</RouterLink><RouterLink :to="`/finance/agreements/${g.id}/payouts/new`" class="button-link primary">提交付款申请</RouterLink><RouterLink :to="`/finance/agreements/${g.id}/readiness`" class="button-link outline">本次付款外部服务状态</RouterLink><RouterLink v-if="isPayer&&g.data.source_type==='RELEASE'" :to="`/finance/agreements/${g.id}/statements/new`" class="button-link outline">登记渠道收入账单</RouterLink><RouterLink v-if="isPayer&&g.data.source_type==='ORDER'" :to="`/finance/agreements/${g.id}/reconciliations/new`" class="button-link outline">支付渠道对账</RouterLink><RouterLink v-if="isPayer" :to="`/finance/agreements/${g.id}/adjustments/new`" class="button-link outline">登记账务调整</RouterLink></div></section><section class="supply-card"><h2>已保存的财务事项</h2><div v-for="r in records" :key="r.id" class="finance-rule-line"><RouterLink :to="`/finance/records/${r.id}`">{{kindLabels[r.kind]}} · {{shortSupplyId(r.id)}} · {{financeStatus(r)}}</RouterLink></div><p v-if="!records.length" class="muted">尚未读取到期间结算、付款申请或异议。</p></section><section class="supply-card"><h2>获准读取的记账历史</h2><div class="table-wrap"><table><thead><tr><th>账项</th><th>主体</th><th>金额</th><th>来源</th></tr></thead><tbody><tr v-for="e in entries" :key="e.id"><td>{{e.category}} · {{e.id}}</td><td>{{shortSupplyId(e.party_id)}}</td><td>{{money(e.amount_minor)}}</td><td>{{shortSupplyId(e.source_id)}}</td></tr></tbody></table></div><button v-if="entryCursor" class="outline" :disabled="locked" @click="loadEntries(true)">继续读取账项</button></section></template>
<template v-if="detail&&mode!=='new'"><div :class="{'finance-columns':reviewer||mode.startsWith('confirm-')}"><div><FinanceRecordPanel :record="detail"/><section v-if="evidenceIds(detail).length" class="supply-card"><h2>私有证明与付款材料</h2><div v-for="id in evidenceIds(detail)" :key="id" class="finance-evidence"><span>{{shortSupplyId(id)}}</span><button class="outline" :disabled="locked" :data-testid="`finance-proof-${id}`" @click="readEvidence(id)">读取私有证明</button><span v-if="readAssets.includes(id)" class="muted">已按当前权限读取</span></div></section><template v-if="reviewer&& section==='disputes'||mode==='respond'"><FinanceRecordPanel v-for="r in records.filter(r=>r.kind==='RESPONSE'&&detail?.kind==='DISPUTE'&&r.data.dispute_id===detail.id)" :key="r.id" :record="r"/></template></div>
<section v-if="reviewer" class="supply-card finance-action-panel"><h2>{{section==='disputes'?'独立处理决定':'本次独立核验'}}</h2><p class="muted">已读取当前记录版本。参与方、记录创建者及约定创建者不可独立审核。</p><form v-if="section!=='disputes'" @submit.prevent="review"><fieldset :disabled="locked||!independent"><div class="evidence-options"><label v-for="(label,key) in reviewChecks" :key="key"><input v-model="verification[key]" :data-testid="`finance-check-${key}`" type="checkbox">{{label}}</label></div><label>审核决定 *<select v-model="decision" data-testid="finance-review-decision" required><option value="">重新明确选择</option><option value="APPROVED">核实通过</option><option value="REJECTED">拒绝</option></select></label><label>事实与理由 *<textarea v-model="reason" data-testid="finance-review-reason" required maxlength="4000"></textarea></label><p class="muted">通过须实际读取所有引用证明并核对四项事实。核验不表示自动支付服务已开通。</p><button class="primary" data-testid="finance-review-submit" :disabled="locked||!reviewValid">提交独立核验</button></fieldset></form><form v-else @submit.prevent="decideDispute"><fieldset :disabled="locked||!independent||!['OPEN','ACTION_REQUIRED'].includes(detail.current_status)"><label>处理决定 *<select v-model="decision" data-testid="finance-dispute-decision" required><option value="">重新明确选择</option><option value="ACTION_REQUIRED">要求另行补救，维持暂停</option><option value="RESUME">准许恢复后续办理</option><option value="REMEDIED">补救事实已核实</option></select></label><template v-if="decision==='REMEDIED'"><label>已核实补救事实编号 *<input v-model="form.action" data-testid="finance-dispute-action" list="finance-actions" placeholder="真实已批准调整或原订单成功退款编号" required></label><datalist id="finance-actions"><option v-for="r in records.filter(r=>r.kind==='ADJUSTMENT'&&r.current_status==='APPROVED')" :key="r.id" :value="r.id">已批准账务调整</option></datalist><p class="muted">目录没有的成功退款须准确填写原事实编号；服务器验证同一原业务、真实成功状态及实际关系。</p></template><label>处理依据 *<textarea v-model="reason" data-testid="finance-dispute-reason" maxlength="8000" required></textarea></label><button class="primary" data-testid="finance-dispute-decision-submit" :disabled="locked||!independent||!decision||!reason.trim()||(decision==='REMEDIED'&&!validSupplyId(form.action))">保存争议处理决定</button></fieldset></form></section>
<section v-if="mode.startsWith('confirm-')" class="supply-card finance-action-panel"><h2>本方准确版本决定</h2><p>{{gate.message}}</p><div v-for="c in confirmations" :key="c.party_id" class="finance-rule-line"><p>{{shortSupplyId(c.party_id)}} · {{c.decision==='APPROVED'?'已同意':'已拒绝'}}</p><p class="long-text">{{c.reason}}</p></div><form @submit.prevent="confirm"><fieldset :disabled="locked||!canOwn||!gate.can"><label>本方决定 *<select v-model="decision" data-testid="finance-confirm-decision" required><option value="">重新明确选择</option><option value="APPROVED">同意准确内容</option><option value="REJECTED">拒绝本版</option></select></label><label>本方确认说明 *<textarea v-model="reason" data-testid="finance-confirm-reason" maxlength="2000" required></textarea></label><button class="primary" data-testid="finance-confirm-submit" :disabled="locked||!canOwn||!gate.can||!decision||!reason.trim()">保存本方确认</button></fieldset></form><p class="muted">提交后将读取实际确认列表，核对本方、原指纹、决定及理由。保存确认不修改原快照。</p></section></div>
<section v-if="mode==='record'" class="supply-card"><h2>按当前事实继续办理</h2><div class="supply-actions"><RouterLink v-if="detail.kind==='AGREEMENT'" :to="`/finance/agreements/${detail.id}`" class="button-link outline">查看约定与本方余额</RouterLink><RouterLink v-if="detail.kind==='SETTLEMENT'" :to="`/finance/settlements/${detail.id}/confirm`" class="button-link primary">本方确认冻结结算单</RouterLink><RouterLink v-if="detail.kind==='PAYOUT'&&isPayer&&['APPROVED','PAID'].includes(detail.current_status)" :to="`/finance/payouts/${detail.id}/evidence`" class="button-link primary">登记真实付款结果</RouterLink><RouterLink v-if="detail.kind==='STATEMENT'&&isPayer&&detail.current_status==='APPROVED'&&detail.data.direction==='CREDIT'" :to="`/finance/statements/${detail.id}/receipts/new`" class="button-link primary">登记渠道实际到账</RouterLink><RouterLink v-if="detail.kind==='DISPUTE'&&['OPEN','ACTION_REQUIRED'].includes(detail.current_status)" :to="`/finance/disputes/${detail.id}/respond`" class="button-link primary">补充争议说明</RouterLink><RouterLink :to="`/finance/records/${detail.id}/disputes/new`" class="button-link outline">对本记录发起异议</RouterLink><RouterLink v-if="g" :to="`/finance/agreements/${g.id}`" class="button-link outline">查看原约定与当前余额</RouterLink></div><form v-if="detail.kind==='PAYOUT'&&detail.current_status==='REQUESTED'&&(isPayer||detail.data.recipient_party_id===session.selectedId)" @submit.prevent="cancelPayout"><label>取消未执行申请的理由 *<textarea v-model="reason" data-testid="finance-cancel-reason" maxlength="2000" :disabled="locked" required></textarea></label><button class="outline" data-testid="finance-payout-cancel" :disabled="locked||!canOwn||!reason.trim()">取消未执行付款申请</button></form></section>
</template>
<form v-if="['settlement','payout','evidence','statement','receipt','adjustment','dispute','respond','reconcile'].includes(mode)&&detail&&g" @submit.prevent="({settlement:settle,payout,evidence:reportEvidence,statement,receipt,adjustment:adjust,dispute,respond,reconcile} as Record<string,()=>unknown>)[mode]?.()"><fieldset :disabled="locked||!canOwn">
<section v-if="mode==='settlement'" class="supply-card"><h2>期间标签与本次冻结说明</h2><label>期间参考 *<input v-model="form.period" data-testid="finance-period" maxlength="128" required></label><label>本次结算说明 *<textarea v-model="form.note" data-testid="finance-note" maxlength="4000" required></textarea></label><p class="muted">期间只是人工标签。服务器按当前已核实实收、退款、账单和调整生成冻结事实，不按标签回填历史。</p></section>
<section v-if="mode==='payout'" class="supply-card"><h2>收款方、明确金额与用途</h2><div class="trade-fields two"><label>实际收款方 *<select v-model="form.recipient" data-testid="finance-recipient" required><option value="">请选择本约定参与方</option><option v-for="id in g.data.parties.filter(id=>id!==g?.owner_party_id&&(isPayer||id===session.selectedId))" :key="id" :value="id">{{id}}</option></select></label><label>申请金额（元） *<input v-model="form.amount" data-testid="finance-amount" inputmode="decimal" required></label></div><label>付款用途与说明 *<textarea v-model="form.note" data-testid="finance-note" maxlength="4000" required></textarea></label><p v-if="balances">本方获准可申请额度：{{balances.items.filter(b=>b.party_id===form.recipient).map(b=>money(b.available_minor)).join('、')||'请选择并核对实际收款方'}}</p><p class="muted">批准仍未实际付款；申请占用额度，真实付款结果另凭实际全额凭据独立核实。收款材料归当前上传主体所有。</p></section>
<section v-if="mode==='evidence'&&detail?.kind==='PAYOUT'" class="supply-card"><h2>真实人工付款结果</h2><div class="trade-fields two"><label>真实报告结果 *<select v-model="form.outcome" data-testid="finance-outcome" required><option value="">明确选择</option><option v-if="detail.current_status==='APPROVED'" value="PAID">原款已全额付出</option><option v-if="detail.current_status==='APPROVED'" value="FAILED">原付款实际失败</option><option v-if="detail.current_status==='PAID'" value="RETURNED">原款已全额退回</option></select></label><label>原全额金额（元） *<input v-model="form.amount" data-testid="finance-amount" inputmode="decimal" required></label><label>真实外部流水参考 *<input v-model="form.reference" data-testid="finance-reference" maxlength="128" required></label><label>实际发生日期时间 *<input v-model="form.time" data-testid="finance-time" type="datetime-local" required></label></div><label>本次事实说明 *<textarea v-model="form.note" data-testid="finance-note" maxlength="4000" required></textarea></label><p class="muted">原付款全额 {{money(detail.data.amount_minor)}}。当前没有部分实付结果接口；不会调用自动支付或把报告直接记为付款成功。</p></section>
<section v-if="mode==='statement'" class="supply-card"><h2>真实渠道账单与净应收</h2><div class="trade-fields two"><label>外部账单参考 *<input v-model="form.reference" data-testid="finance-reference" maxlength="128" required></label><label>账单性质 *<select v-model="form.direction" data-testid="finance-statement-direction" required @change="form.original=''"><option value="">明确选择</option><option value="CREDIT">原应收账单</option><option value="DEBIT">冲减已批准原账单</option></select></label><label>期间开始 *<input v-model="form.start" data-testid="finance-period-start" type="datetime-local" required></label><label>期间结束 *<input v-model="form.end" data-testid="finance-period-end" type="datetime-local" required></label><label v-for="(label,key) in {gross:'渠道总收入',refund:'渠道退款',fee:'渠道费用',tax:'真实税费'}" :key="key">{{label}}（元） *<input v-model="form[key]" :data-testid="`finance-${key}`" inputmode="decimal" required placeholder="零也须明确填写"></label></div><label v-if="form.direction==='DEBIT'">被冲减的原账单 *<select v-model="form.original" data-testid="finance-original-statement" required><option value="">请选择同约定已批准 CREDIT</option><option v-for="r in records.filter(r=>r.kind==='STATEMENT'&&r.current_status==='APPROVED'&&r.data.direction==='CREDIT')" :key="r.id" :value="r.id">{{r.id}} · {{r.kind==='STATEMENT'?money(r.data.net_minor):''}}</option></select></label><p>本次净额：{{statementNet===null?'待明确全部金额':money(form.direction==='DEBIT'?-statementNet:statementNet)}}。净额不得为负；累计冲减不得超过原账单。</p><label>账单说明 *<textarea v-model="form.note" data-testid="finance-note" maxlength="4000" required></textarea></label><p class="muted">核验账单只登记应收；另有银行到账凭据才可登记实际到账。</p></section>
<section v-if="mode==='receipt'" class="supply-card"><h2>实际到账金额与流水</h2><div class="trade-fields two"><label>本次实际到账（元） *<input v-model="form.amount" data-testid="finance-amount" inputmode="decimal" required></label><label>真实外部流水参考 *<input v-model="form.reference" data-testid="finance-reference" maxlength="128" required></label><label>实际到账日期时间 *<input v-model="form.time" data-testid="finance-time" type="datetime-local" required></label></div><label>实际到账说明 *<textarea v-model="form.note" data-testid="finance-note" maxlength="4000" required></textarea></label><p class="muted">累计核实到账不能超过同一已批准原账单净额。此报告经独立核实后才计入实收。</p></section>
<section v-if="mode==='adjustment'" class="supply-card"><h2>同一约定内的零和调整</h2><div v-for="(e,n) in adjustment" :key="n" class="trade-fields two finance-rule-line"><label>调整主体 *<select v-model="e.party" :data-testid="`finance-adjustment-party-${n}`" required><option value="">请选择实际参与方</option><option v-for="id in g.data.parties" :key="id" :value="id">{{id}}</option></select></label><label>调整金额（元，可负） *<input v-model="e.amount" :data-testid="`finance-adjustment-amount-${n}`" inputmode="decimal" required></label><button v-if="adjustment.length>2" type="button" class="danger" @click="adjustment.splice(n,1)">移除调整方</button></div><button type="button" class="outline" data-testid="finance-adjustment-add" :disabled="adjustment.length>=30" @click="adjustment.push({party:'',amount:''})">添加调整方</button><label>真实调整依据 *<textarea v-model="reason" data-testid="finance-adjustment-reason" maxlength="4000" required></textarea></label><p class="muted">各方金额之和须为零，主体不能重复。审核通过后保留独立记账历史，再重新生成结算单；不修改原付款。</p></section>
<section v-if="mode==='dispute'" class="supply-card"><h2>异议事项与事实依据</h2><label>异议类别 *<select v-model="form.category" data-testid="finance-dispute-category" required><option value="">明确选择</option><option value="QUALITY">质量</option><option value="REFUND">退款</option><option value="RIGHTS_DEFECT">权利缺陷</option><option value="EXCLUSIVITY">独占冲突</option><option value="SETTLEMENT">结算</option><option value="OTHER">其他</option></select></label><label>具体事实与要求 *<textarea v-model="reason" data-testid="finance-dispute-reason" maxlength="8000" required></textarea></label><p class="muted">发起异议会暂停本约定新付款；不会自动退款、调整账务或改变许可。</p></section>
<section v-if="mode==='respond'" class="supply-card"><h2>对本次争议补充说明</h2><label>补充事实与说明 *<textarea v-model="form.message" data-testid="finance-response-message" maxlength="8000" required></textarea></label><p class="muted">补充说明单独保存，不能覆盖原异议。可另附实际证明，独立处理人员作出后续决定。</p></section>
<section v-if="mode==='reconcile'" class="supply-card"><h2>真实外部支付账单</h2><div class="trade-fields three"><label>支付渠道 *<select v-model="form.provider" data-testid="finance-provider" required><option value="">明确选择</option><option value="ALIPAY">支付宝</option><option value="APPLE">Apple</option></select></label><label>账单环境 *<select v-model="form.environment" data-testid="finance-reconciliation-environment" required><option value="">明确选择且与约定一致</option><option value="SANDBOX">沙盒</option><option value="PRODUCTION">正式</option></select></label><label>外部账单参考 *<input v-model="form.reference" data-testid="finance-reference" maxlength="128" required></label></div><div v-for="(e,n) in externalLines" :key="n" class="finance-rule-line"><div class="trade-fields two"><label>实际收款 / 退款记录编号 *<input v-model="e.record" :data-testid="`finance-reconcile-record-${n}`" required placeholder="准确平台事实编号"></label><label>方向 *<select v-model="e.direction" :data-testid="`finance-reconcile-direction-${n}`" required><option value="">明确选择</option><option value="RECEIPT">收款</option><option value="REFUND">退款</option></select></label><label>实际外部流水参考 *<input v-model="e.reference" :data-testid="`finance-reconcile-reference-${n}`" maxlength="128" required></label><label>外部金额（元） *<input v-model="e.amount" :data-testid="`finance-reconcile-amount-${n}`" inputmode="decimal" required></label></div><button type="button" class="danger" @click="externalLines.splice(n,1)">移除比较明细</button></div><button type="button" class="outline" data-testid="finance-reconcile-add" :disabled="externalLines.length>=200" @click="externalLines.push({record:'',direction:'',reference:'',amount:''})">添加真实外部明细</button><p class="muted">最多 200 条，空列表用于实际账单没有明细的比较。只比较正式已核实平台事实；不补造实收、不自动支付、不替代人工审核。</p></section>
<section v-if="mode!=='settlement'" class="supply-card"><h2>{{mode==='respond'?'可选补充材料':'本次实际私有凭据'}}</h2><SupplyUpload :key="securityRevision" :label="mode==='payout'?'实际收款材料':mode==='respond'?'争议补充材料':'财务事实证明'" :ids="assets" :disabled="locked||assets.length>=30" :single="!['dispute','respond'].includes(mode)" @upload="upload" @remove="removeAsset"/></section><section class="supply-card"><h2>提交并保留本次历史</h2><p v-if="!isPayer&&!['payout','dispute','respond'].includes(mode)" class="supply-warning">本项由原约定付款方负责人办理。当前身份不能登记付款、收入或调整事实。</p><button v-if="mode==='settlement'" class="primary" data-testid="finance-settlement-submit" :disabled="locked||!isPayer||!form.period.trim()||!form.note.trim()">生成结算单待独立复核</button><button v-if="mode==='payout'" class="primary" data-testid="finance-payout-submit" :disabled="locked||!payoutValid">提交付款申请待复核</button><button v-if="mode==='evidence'" class="primary" data-testid="finance-evidence-submit" :disabled="locked||!isPayer||!form.outcome||!positive(form.amount)||!form.reference.trim()||!past(form.time)||!form.note.trim()||assets.length!==1">登记付款结果待独立核实</button><button v-if="mode==='statement'" class="primary" data-testid="finance-statement-submit" :disabled="locked||!statementValid">登记账单待独立核验</button><button v-if="mode==='receipt'" class="primary" data-testid="finance-receipt-submit" :disabled="locked||!isPayer||!positive(form.amount)||!form.reference.trim()||!past(form.time)||!form.note.trim()||assets.length!==1">登记到账待独立核验</button><button v-if="mode==='adjustment'" class="primary" data-testid="finance-adjustment-submit" :disabled="locked||!adjustmentValid">登记零和调整待复核</button><button v-if="mode==='dispute'" class="primary" data-testid="finance-dispute-submit" :disabled="locked||!canOwn||!form.category||!reason.trim()||!assets.length">发起异议并暂停新付款</button><button v-if="mode==='respond'" class="primary" data-testid="finance-response-submit" :disabled="locked||!canOwn||!form.message.trim()||detail?.kind!=='DISPUTE'||!['OPEN','ACTION_REQUIRED'].includes(detail.current_status)">保存本次补充说明</button><button v-if="mode==='reconcile'" class="primary" data-testid="finance-reconcile-submit" :disabled="locked||!isPayer||g.data.source_type!=='ORDER'||!form.provider||form.environment!==g.data.environment||!form.reference.trim()||assets.length!==1">保存比较结果</button></section></fieldset></form>
<section v-if="mode==='readiness'&&g" class="supply-card"><h2>仅针对本次约定的付款服务条件</h2><button class="outline" data-testid="finance-readiness-refresh" :disabled="locked" @click="refreshReadiness">重新读取当前约定状态</button><template v-if="readiness"><p>当前环境：{{readiness.environment==='SANDBOX'?'沙盒':'正式'}}</p><div class="finance-readiness"><h3>自动出款</h3><span class="status-chip">尚未实现 / 尚未核实渠道</span><p>当前接口不提供自动出款；不能据此视为正式支付渠道已开通。</p></div><div class="finance-readiness"><h3>真实人工付款与独立核实</h3><span class="status-chip">记录与核实流程可用</span><p>实际在外部支付完成后登记原全额凭据，再由独立人员核实；记录功能不代表已实际付款。</p></div><RouterLink :to="`/finance/agreements/${g.id}/payouts/new`" class="button-link outline">返回本约定付款申请</RouterLink></template><p v-else class="supply-empty">尚未读取此约定的真实服务状态。</p></section>
</div></main></div></div></template>
